begin
 select pr.* into p from public.apertura_proyectos pr join public.sucursales s on s.id=pr.sucursal_id where lower(trim(s.nombre))='dodo-2' for update of pr;
 if not found then raise exception 'Primero carga el proyecto de dodo-2.';end if;
 select pr.id into a from public.perfiles pr join auth.users u on u.id=pr.id where lower(u.email)='scervera@dodopizza.mx' and pr.rol::text='admin' and pr.activo and not pr.debe_cambiar_contrasena;
 if a is null then raise exception 'No se encontró la cuenta administradora autorizada scervera@dodopizza.mx.';end if;
 -- La misma carga no reescribe modificaciones posteriores ni duplica registros.
 if exists(select 1 from public.apertura_items where proyecto_id=p.id and clave='PRE26-CORTE') then return;end if;
 for x in select value from jsonb_array_elements(datos->'cambios') loop
  select * into i from public.apertura_items where proyecto_id=p.id and clave=x->>'clave' for update;
  if not found or i.nombre is distinct from x->>'nombre_esperado' then raise exception 'No coincide el registro %; conciliar antes de actualizar.',x->>'clave';end if;
  if i.revision<>1 or i.recibido<>0 or i.orden_id is not null or i.factura_id is not null then raise exception 'El registro % tiene seguimiento posterior; conciliar antes de actualizar.',i.clave;end if;
 end loop;
 antes:=to_jsonb(p);
 update public.apertura_proyectos set presupuesto=3357562.35,revision=revision+1 where id=p.id returning to_jsonb(apertura_proyectos.*) into despues;
 insert into public.apertura_proyecto_historial(proyecto_id,anterior,nuevo,usuario_id) values(p.id,antes,despues,a);
 for x in select value from jsonb_array_elements(datos->'cambios') loop
  select * into i from public.apertura_items where proyecto_id=p.id and clave=x->>'clave' for update;
  antes:=to_jsonb(i);
  update public.apertura_items set estado=x->>'estado',responsable=coalesce(responsable,'Julio Veredeja'),notas=concat_ws(E'\n',notas,marca||': '||(x->>'notas')),evidencia=concat_ws(E'\n',evidencia,'Dodo2_Presupuesto_Final.xlsx / Lista HQ (control) / corte 13/10/2026'),revision=revision+1,actualizado_en=now() where id=i.id returning to_jsonb(apertura_items.*) into despues;
  insert into public.apertura_historial(item_id,anterior,nuevo,usuario_id) values(i.id,antes,despues,a);
 end loop;
 for x in select value from jsonb_array_elements(datos->'nuevos') loop
  insert into public.apertura_items(proyecto_id,clave,tipo,etapa,nombre,fuente,original,estado,responsable,cantidad,notas,evidencia)
  values(p.id,x->>'clave',x->>'tipo',x->>'etapa',x->>'nombre','Dodo2_Presupuesto_Final.xlsx / corte 13/10/2026',x->'original',x->>'estado','Julio Veredeja',(x->>'cantidad')::numeric,x->>'notas','Presupuesto final, corte 13 de octubre de 2026. SHA-256 conservado en fuente.') returning * into i;
  insert into public.apertura_historial(item_id,anterior,nuevo,usuario_id) values(i.id,'{}',to_jsonb(i),a);
 end loop;
end $$;
